    (7, 'base', 'Transitividade verbal', 4, 'Em "Ela precisa de ajuda", o verbo "precisar" é:', 'transitivo indireto', [('transitivo direto', 'Não notou a preposição "de"'), ('intransitivo', 'O verbo pede complemento'), ('de ligação', 'Não liga característica'), ('bitransitivo', 'Só há um complemento')], 'Quem precisa, precisa DE algo: complemento com preposição.'),
