    (7, 'olimpico', 'Metáfora', 5, 'Qual frase traz uma METÁFORA?', 'A sala de aula era um formigueiro.', [('A sala parecia um formigueiro.', 'É comparação (parecia)'), ('As formigas trabalham muito.', 'Sentido literal'), ('A sala estava barulhenta.', 'Sem figura'), ('A sala, como um formigueiro, fervia.', 'É comparação (como)')], 'Metáfora: comparação sem termo comparativo.'),
    (7, 'olimpico', 'Hipérbole', 5, 'Qual frase usa exagero proposital (hipérbole)?', 'Já te falei isso um milhão de vezes!', [('Falei isso duas vezes.', 'Literal'), ('Ele fala como um papagaio.', 'Comparação'), ('O silêncio gritava na sala.', 'Paradoxo/personificação'), ('Falei baixinho.', 'Literal')], 'Um milhão de vezes é exagero para dar ênfase.'),
