    (9, 'bolsa', 'Coesão: conectivo', 4, 'O conectivo "Ocorre que" introduz:', 'um contra-argumento à ideia anterior', [('uma conclusão', 'Não fecha o texto'), ('um exemplo', 'Não exemplifica'), ('uma enumeração', 'Não lista'), ('uma explicação de causa', 'Não explica motivo')], 'Após "parece desperdício", "ocorre que" apresenta a objeção do autor.', 't9'),
    (9, 'bolsa', 'Interpretação: nuance', 5, 'Segundo o texto, defender a leitura lenta significa:', 'reconhecer que alguns conteúdos pedem tempo, sem rejeitar a velocidade', [('abandonar a tecnologia', 'Inventou'), ('ler tudo devagar', 'Generalizou'), ('recusar a velocidade', 'O texto nega isso'), ('ler só poemas', 'Generalizou')], '"Não é recusar a velocidade, mas lembrar que nem tudo cabe em três minutos."', 't9'),
    (9, 'bolsa', 'Linguagem: enumeração', 4, 'No primeiro período, a enumeração de exemplos serve para:', 'caracterizar a "era da pressa"', [('criticar os vídeos', 'Não é o foco'), ('ensinar a usar a internet', 'Inventou'), ('provar que resumos são bons', 'Inverteu'), ('apresentar a conclusão', 'Está no começo')], 'Vídeos acelerados, resumos, mensagens: exemplos da pressa.', 't9'),
    (9, 'olimpico', 'Paradoxo', 5, 'Qual frase traz um PARADOXO?', 'Era um silêncio ensurdecedor.', [('Era um silêncio profundo.', 'Sem contradição'), ('O silêncio parecia eterno.', 'Hipérbole'), ('Silêncio, por favor!', 'Apelo'), ('O silêncio voltou à sala.', 'Literal')], 'Silêncio não pode ensurdecer: ideia contraditória que produz sentido.'),
    (9, 'olimpico', 'Variação linguística', 5, 'A frase "Nóis vai na feira" é:', 'uma variante popular, adequada a contextos informais', [('um erro sem sentido', 'A frase comunica'), ('a forma da norma-padrão', 'A padrão é "Nós vamos à feira"'), ('uma frase de outra língua', 'É português'), ('uma gíria de internet', 'Não é gíria digital')], 'É variação linguística: comunica, mas não segue a norma-padrão.'),
    (9, 'olimpico', 'Intertextualidade', 5, 'Uma propaganda diz: "Ser ou não ser… cliente? Eis a questão!". Ela dialoga com:', 'uma frase famosa de uma peça de teatro', [('uma lei', 'Não é texto legal'), ('uma notícia de jornal', 'Não'), ('um poema de cordel', 'Não'), ('uma receita', 'Não')], 'Retoma "Ser ou não ser, eis a questão", da peça Hamlet, de Shakespeare.'),
    (9, 'olimpico', 'Concordância especial', 5, 'Qual frase está correta?', 'Mais de um aluno faltou.', [('Mais de um aluno faltaram.', 'Com "mais de um" o verbo fica no singular'), ('Haviam três alunos.', '"Haver" de existir é impessoal'), ('Faltou dois alunos.', 'O verbo concorda com "dois alunos"'), ('Fazem três dias.', '"Fazer" de tempo é impessoal')], 'Com "mais de um", o verbo concorda com "um": singular.'),
