def gerar_portugues(montar, novo_id, rng):
    for item in ITENS:
        serie, col, hab, dif, enun, correta, erradas, expl = item[:8]
        apoio = TEXTOS[item[8]] if len(item) > 8 else None
        bloco = 'por-interpretacao' if col == 'bolsa' else ('por-linguagem' if col == 'olimpico' else 'por-gramatica')
        montar(novo_id(f'l2-por{serie}'), serie, col, 'portugues', bloco, hab, dif, enun, correta, erradas, expl, None, apoio)
